package api.publica;
import java.time.LocalDateTime;import java.util.List;
public final class InvitacionComunidadDTO {private InvitacionComunidadDTO(){} public record Enviar(long perfilDestinatarioId,String objetivo,String mensaje){} public record Perfil(long perfilId,String nombre,String iniciales,String posicion,String categoria,String color){} public record Invitacion(long invitacionId,String objetivo,String estado,String mensaje,LocalDateTime fechaInvitacion,LocalDateTime fechaResolucion,LocalDateTime fechaExpiracion,long version,boolean pendiente,Perfil emisor,Perfil destinatario){} public record Contacto(boolean disponible,String estado,String mensaje,String nombre,String urlWhatsapp){} public record Listado(List<Invitacion> invitaciones,int total){public Listado{invitaciones=invitaciones==null?List.of():List.copyOf(invitaciones);}}}
